<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
import {api,can,type Configuration,type DataSnapshot,type DataSnapshotSummary} from './api';
import {displayMetric,unit,qualityNames} from './units';
import DataJobs from './DataJobs.vue';
const props=defineProps<{config:Configuration;canOperate:boolean}>();
const rows=ref<DataSnapshotSummary[]>([]),details=ref<DataSnapshot|null>(null),name=ref('手动数据快照'),error=ref(''),message=ref(''),busy=ref(false),jobs=ref<InstanceType<typeof DataJobs>|null>(null);let timer:ReturnType<typeof setInterval>|undefined;
async function load(){try{rows.value=await api('/api/snapshots')}catch(e){error.value=String(e)}}
async function capture(){if(busy.value)return;busy.value=true;try{await api('/api/snapshots','POST',{name:name.value,tankIds:null});message.value='已申请抓取全部启用储罐的快照；停用罐排除，隐藏罐保留。无效读数按当时状态保存。';await jobs.value?.load();error.value=''}catch(e){error.value=String(e)}finally{busy.value=false}}
async function open(id:string){try{details.value=await api('/api/snapshots/'+id)}catch(e){error.value=String(e)}}
function exportSnapshot(){if(!details.value||!can('DataExport'))return;const d=props.config.display;window.LocalWorkbook.download('数据快照',[{name:'快照',rows:[['快照名称',details.value.name],['快照时间',new Date(details.value.atUtc).toLocaleString('zh-CN',{hour12:false})],['配置版本',details.value.configurationRevision],['储罐','液位 '+unit('level',d),'温度 ℃','平均温度 ℃','密度 '+unit('density',d),'净体积 '+unit('volume',d),'质量 '+unit('mass',d),'液位状态'],...details.value.readings.map(r=>[props.config.tanks.find(t=>t.id===r.tankId)?.code||r.tankId,displayMetric(r.levelMm,'level',d),displayMetric(r.instantTemperatureC,'temperature',d),displayMetric(r.averageTemperatureC,'temperature',d),displayMetric(r.instrumentDensityKgM3,'density',d),displayMetric(r.netVolumeM3,'volume',d),displayMetric(r.massT,'mass',d),qualityNames[r.levelMm.quality]])]}])}
onMounted(()=>{void load();timer=setInterval(()=>void load(),3000)});onUnmounted(()=>{if(timer)clearInterval(timer)});
</script>
<template><div class="notice">快照单独保存某一时刻的读数、状态和配置版本，用于交班、盘点核对。它不会启动仪表动作，也不代替按间隔保存的历史。</div><p v-if="error" role="alert" class="notice error-message">{{error}}</p><p v-if="message" role="status" class="notice success-message">{{message}}</p><form v-if="canOperate" class="panel query-panel" @submit.prevent="capture"><div class="query-fields"><label class="config-field">快照名称<input v-model="name" required maxlength="100"></label></div><button class="button primary" :disabled="busy">抓取数据快照</button></form><section class="panel"><div class="toolbar"><h2>最近100份快照</h2><button class="button" @click="load">刷新</button></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>名称</th><th>有效液位 / 罐数</th><th>配置版本</th><th>人员</th><th>操作</th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td>{{new Date(s.atUtc).toLocaleString('zh-CN',{hour12:false})}}</td><td>{{s.name}}</td><td>{{s.validLevels}} / {{s.rows}}</td><td>{{s.configurationRevision}}</td><td>{{s.actorName}}</td><td><button class="text-button" @click="open(s.id)">查看快照</button></td></tr><tr v-if="!rows.length"><td colspan="6" class="empty">尚未抓取快照</td></tr></tbody></table></div></section><DataJobs ref="jobs" kind="Snapshot"/><div v-if="details" class="modal-backdrop"><section class="modal wide-modal" role="dialog" aria-label="数据快照明细"><div class="modal-head"><h2>{{details.name}}</h2><div><button class="button" :disabled="!can('DataExport')" @click="exportSnapshot">导出快照</button><button class="button" @click="details=null">关闭</button></div></div><div class="modal-body"><p>{{new Date(details.atUtc).toLocaleString('zh-CN',{hour12:false})}} · 配置版本 {{details.configurationRevision}} · 保留当时结果</p><div class="table-wrap"><table><thead><tr><th>储罐</th><th>液位 {{unit('level',config.display)}}</th><th>温度 ℃</th><th>平均温度 ℃</th><th>净体积 {{unit('volume',config.display)}}</th><th>质量 {{unit('mass',config.display)}}</th><th>液位状态</th></tr></thead><tbody><tr v-for="r in details.readings" :key="r.tankId"><td>{{config.tanks.find(t=>t.id===r.tankId)?.code||r.tankId}}</td><td>{{displayMetric(r.levelMm,'level',config.display)}}</td><td>{{displayMetric(r.instantTemperatureC,'temperature',config.display)}}</td><td>{{displayMetric(r.averageTemperatureC,'temperature',config.display)}}</td><td>{{displayMetric(r.netVolumeM3,'volume',config.display)}}</td><td>{{displayMetric(r.massT,'mass',config.display)}}</td><td>{{qualityNames[r.levelMm.quality]}}</td></tr></tbody></table></div></div></section></div></template>
